tail -50 xtb_opt.log | sed -n '1,50p'
python3 - <<'PY'
import numpy as np
fn='xtb_opt.xyz'
ls=open(fn).read().splitlines(); n=int(ls[0]); print('n',n,'comment',ls[1])
sy=[]; co=[]
for l in ls[2:]:
 p=l.split(); sy.append(p[0]); co.append(list(map(float,p[1:4])))
co=np.array(co)
def d(i,j): return np.linalg.norm(co[i]-co[j])
def ang(i,j,k):
 v=co[i]-co[j]; w=co[k]-co[j]
 return np.degrees(np.arccos(np.dot(v,w)/np.linalg.norm(v)/np.linalg.norm(w)))
print('distances Ir-H',d(0,1),d(0,2),'Ir-Cl',d(0,3),d(0,4),'Ir-P',d(0,8),d(0,39))
print('trans angles P-Ir-P',ang(8,0,39),'H-Ir-H',ang(1,0,2),'Cl-Ir-Cl',ang(3,0,4))
print('cis angles:')
for a,b in [(8,1),(8,2),(39,1),(39,2),(8,3),(8,4),(39,3),(39,4),(1,3),(1,4),(2,3),(2,4)]: print(a,b,ang(a,0,b))
# Close interligand/non-core contacts excluding obvious covalent rough connections; list all under 2.0
pairs=[]
for i in range(n):
 for j in range(i+1,n):
  dd=d(i,j)
  if dd<2.0:
   pairs.append((dd,i,j,sy[i],sy[j]))
print('pairs<2.0')
for x in sorted(pairs): print(x)
PY
